import{useEffect,useState}from"react";import{getVendorOrders,updateProductOrderStatus}from"../../api/productApi";
const statuses=["CONFIRMED","PROCESSING","PACKED","READY_FOR_PICKUP","COLLECTED","SHIPPED","OUT_FOR_DELIVERY","DELIVERED","CANCELLED"];
export default function ProductOrders(){const[data,setData]=useState([]),[ed,setEd]=useState({}),[msg,setMsg]=useState("");const load=()=>getVendorOrders().then(r=>setData(r.data?.data||[])).catch(e=>setMsg(e.response?.data?.message||"Could not load orders"));useEffect(()=>{load()},[]);const update=async x=>{try{const v=ed[x.id]||{};await updateProductOrderStatus(x.id,{status:v.status||null,paymentStatus:v.paymentStatus||null,note:v.note||"Vendor order update"});setMsg("Order updated successfully");load()}catch(e){setMsg(e.response?.data?.message||"Could not update order")}};return <div className="page-shell"><p className="eyebrow">VENDOR OPERATIONS</p><h1 className="page-title">Product orders</h1><p className="mt-2 text-sm text-slate-500">Update fulfilment status and review payment status. Only admin can confirm received payments or refunds.</p>{msg&&<div className="mt-4 rounded-xl bg-slate-900 p-3 text-sm text-white">{msg}</div>}<div className="mt-6 space-y-4">{data.map(x=><section className="card p-5" key={x.id}><div className="flex flex-wrap items-start justify-between gap-3"><div><b>{x.orderNumber}</b><p className="mt-1 text-sm text-slate-500">{x.items?.map(i=>`${i.name} × ${i.quantity}`).join(", ")}</p><p className="mt-2 font-black">₹{Number(x.total||0).toLocaleString("en-IN")}</p></div><div className="text-right text-sm"><span className="status-pill bg-slate-100">{x.status}</span><p className="mt-2">Payment: <b>{x.paymentStatus||"PENDING"}</b></p><p className="text-xs text-slate-500">{x.fulfillmentType||"DELIVERY"}</p></div></div><div className="mt-4 grid gap-3 sm:grid-cols-2"><label><span className="label">Order status</span><select className="input" value={ed[x.id]?.status||x.status} onChange={e=>setEd({...ed,[x.id]:{...ed[x.id],status:e.target.value}})}>{[x.status,...statuses].filter((v,i,a)=>a.indexOf(v)===i).map(v=><option key={v}>{v}</option>)}</select></label><label><span className="label">Payment status</span><select className="input" value={ed[x.id]?.paymentStatus||x.paymentStatus||"PENDING"} onChange={e=>setEd({...ed,[x.id]:{...ed[x.id],paymentStatus:e.target.value}})}><option>PENDING</option><option>PROOF_SUBMITTED</option></select></label></div><button className="btn-primary mt-3" onClick={()=>update(x)}>Save updates</button></section>)}{!data.length&&<div className="card p-8 text-center text-slate-400">No product orders yet.</div>}</div></div>}
